mod version;

use async_trait::async_trait;

use version::ShowVersion;

use crate::{
    cmd_uri::CmdUri,
    component::{AzCmd, AzCmdComponent, AzCmdGroup, AzComponentCtx},
    error::{AzError, AzInternalError},
    pb::{
        cmd_interface, execute_response, CmdComponent, CmdHelp, CmdInterface, CmdOutputFormat,
        CmdParams,
    },
};

#[derive(Debug, Default)]
pub struct TopComponent {}

// will be generated by component macro later
#[async_trait]
impl AzCmdGroup for TopComponent {
    const URI: &'static str = "cmd://azure/";

    fn cmd_interface(depth: Option<u32>) -> CmdInterface {
        let groups = vec![];
        let mut commands = vec![];
        if depth.is_none_or(|d| d > 0) {
            let depth = depth.map(|d| d - 1);
            commands.push(ShowVersion::cmd_interface(depth));
        }
        CmdInterface {
            name: "".to_string(),
            help: Some(CmdHelp {
                short: "Contain the top level commands".to_string(),
                long: Some(COMPONENT_LONG_SUMMARY.to_string()),
            }),
            uri: Self::URI.to_string(),
            level: Some(cmd_interface::Level::Component(CmdComponent {
                version: "1.0.0".to_string(),
                groups,
                commands,
            })),
        }
    }

    fn get_interface(
        depth: Option<u32>,
        mut segments: impl Iterator<Item = String>,
    ) -> Option<CmdInterface> {
        match segments.next().as_deref() {
            None => Some(Self::cmd_interface(depth)),
            Some("version") => Some(ShowVersion::cmd_interface(depth)),
            _ => None,
        }
    }

    fn resolve_cmd_uri(mut segments: impl Iterator<Item = String>) -> Option<CmdUri> {
        match segments.next().as_deref() {
            None => Some(Self::uri()),
            Some("version") => Some(ShowVersion::uri()),
            _ => None,
        }
    }

    async fn execute_group<T: AzComponentCtx>(
        ctx: &T,
        mut segments: impl Iterator<Item = String> + Send,
        params: Option<CmdParams>,
        output_format: Option<CmdOutputFormat>,
    ) -> Result<execute_response::Data, AzError> {
        match segments.next().as_deref() {
            Some("version") => ShowVersion::execute(ctx, params, output_format).await,
            Some(other) => Err(AzInternalError::InvalidCmdUriError(other.to_string()).into()),
            None => Err(AzInternalError::InvalidCmdUriError(Self::uri().to_string()).into()),
        }
    }
}

const COMPONENT_LONG_SUMMARY: &str = r"
     /\
    /  \    _____   _ _  ___ _
   / /\ \  |_  / | | | \'__/ _\
  / ____ \  / /| |_| | | |  __/
 /_/    \_\/___|\__,_|_|  \___|

 Welcome to the cool new Azure CLIENT TOOL!
";

// should be generated by component macro later
impl<T: AzComponentCtx> AzCmdComponent<T> for TopComponent {}
